UPDATE `quest_template` SET `NextQuestIdChain`=0, `RewardXPId`=5, `RewardOrRequiredMoney`=75, `RewardMoneyMaxLevel`=210, `Flags`=524288, `RewardChoiceItemId2`=5761, `RewardChoiceItemId4`=12446, `RewardFactionId2`=0, `RewardFactionValueId2`=0, `Title`='The Troll Menace', `Objectives`='Kill 10 Frostmane Troll Whelps.', `Details`='The trolls''re acting up.  More than usual, I''d say.  We''ve seen them put together war parties before, but this time it''s... different.$b$bWhat matters most, however, is the continued protection of Anvilmar.  I''ve no intention to let these trolls flank Anvilmar while its attention is turned towards troggs.  Go thin their ranks a bit.  They need to know that we''re still not without defenses.', `WDBVerified`=15595 WHERE `Id`=182; -- The Troll Cave
UPDATE `quest_template` SET `RewardXPId`=5, `RewardMoneyMaxLevel`=150, `Flags`=16392, `RewardReputationMask`=3, `RewardChoiceItemId3`=57533, `RewardChoiceItemCount3`=1, `Objectives`='Talin Keeneye would like you to kill 12 Small Crag Boars.', `RequiredNpcOrGoCount1`=12, `WDBVerified`=15595 WHERE `Id`=183; -- The Boar Hunter
UPDATE `quest_template` SET `Level`=10, `MinLevel`=9, `RewardMoneyMaxLevel`=390, `RewardReputationMask`=1, `RewardItemId1`=0, `RewardItemId2`=0, `RewardItemCount1`=0, `RewardItemCount2`=0, `RewardFactionValueId1`=5, `Objectives`='Bring Furlbrow''s Deed to the Jansen Stead in Westfall.', `Details`='This is an old deed to an expanse of farmlands within Westfall.  It is signed by a Theodore Furlbrow and cosigned by his wife, Verna.  And on the back of the deed are hastily scrawled words:$B$B\"We leaned on Furlbrow and got his deed.  Thought it might be handy if you wanted to forge one of these for your own place.$B$BThe Furlbrows won''t give us trouble.  Last I saw them they were on their way out of Westfall, stuck with a broken wagon.\"$B$BYou think the Furlbrows might want their deed back...', `WDBVerified`=15595 WHERE `Id`=184; -- Furlbrow's Deed
UPDATE `quest_template` SET `Level`=25, `MinLevel`=24, `RewardXPId`=5, `RewardMoneyMaxLevel`=12000, `Flags`=65544, `Title`='Tiger Hunting', `Objectives`='Hunt 10 Young Stranglethorn Tigers.', `Details`='When I was but a young girl, my father trained me in the art of tiger hunting.$b$bYou''ll find the young felines much easier to track and slay.  One can often find young tigers near the expedition camp.$b$bTest your tracking skills and see if you can hunt some of the beasts down.  Start your hunt near our camp, to the south.', `CompletedText`='Return to Ajeck Rouack at Nesingwary''s Expedition in Northern Stranglethorn.', `WDBVerified`=15595 WHERE `Id`=185; -- Tiger Mastery
UPDATE `quest_template` SET `Level`=26, `MinLevel`=24, `RewardXPId`=5, `RewardMoneyMaxLevel`=12600, `Flags`=589824, `Title`='Tiger Stalking', `Objectives`='Hunt 10 Stranglethorn Tigers.', `Details`='Young tigers are one thing.  Fully-grown cats are another.  Hunting the grown Stranglethorn tigers will prove an even greater challenge.$b$bThe adult cats normally spend their days south of Kurzen''s Compound, east of the river.', `CompletedText`='Return to Ajeck Rouack at Nesingwary''s Expedition in Northern Stranglethorn.', `WDBVerified`=15595 WHERE `Id`=186; -- Tiger Mastery
UPDATE `quest_template` SET `Level`=27, `MinLevel`=24, `RewardXPId`=5, `RewardMoneyMaxLevel`=13200, `Flags`=589824, `Title`='Tiger Prowess', `Objectives`='Hunt 5 Elder Stranglethorn Tigers.', `Details`='Elder Stranglethorn tigers are the strongest of the bunch.  More than one $r $c has seen $g his: her; own demise at the tip of those razor-sharp teeth and heavy claws.$b$bAjeck will be thrilled to know that you have bested them.  The largest pack of these elders can be found to the south, near the Sundering, on the border of the Cape of Stranglethorn.', `CompletedText`='Return to Ajeck Rouack at Nesingwary''s Expedition in Northern Stranglethorn.', `RequiredNpcOrGoCount1`=5, `WDBVerified`=15595 WHERE `Id`=187; -- Tiger Mastery
UPDATE `quest_template` SET `Level`=28, `MinLevel`=24, `RewardXPId`=6, `RewardOrRequiredMoney`=7000, `RewardMoneyMaxLevel`=17100, `Flags`=134742016, `MinimapTargetMark`=16, `QuestGiverPortrait`=698, `RewardItemId1`=0, `RewardItemCount1`=0, `RewardChoiceItemId1`=61116, `RewardChoiceItemId2`=61115, `RewardChoiceItemId3`=61114, `RewardChoiceItemId4`=61113, `RewardChoiceItemCount1`=1, `RewardChoiceItemCount2`=1, `RewardChoiceItemCount3`=1, `RewardChoiceItemCount4`=1, `Objectives`='Hunt Sin''Dall and return with her paw.', `Details`='Legends speak of an elusive tigress... a feline so powerful that she dwarfs even the elder males.  The hunters at Nesingwary''s Expedition have hunted for her without success.  Many of them have fallen prey to her raking claws, their bodies now decaying at the foot of her hill, north of Grom''gol.$b$bThey call the beast Sin''Dall.$b$bYou resolve to do what no $r has done before: hunt, kill, and claim the paw of Sin''Dall.', `CompletedText`='Return to Ajeck Rouack at Nesingwary''s Expedition in Northern Stranglethorn.', `QuestGiverTextWindow`='She prefers to look down upon the weaker tigers from atop her hill.', `QuestGiverTargetName`='Sin''Dall', `WDBVerified`=15595 WHERE `Id`=188; -- Tiger Mastery
UPDATE `quest_template` SET `RewardMoneyMaxLevel`=14700, `Flags`=16392, `WDBVerified`=15595 WHERE `Id`=189; -- Bloodscalp Ears
UPDATE `quest_template` SET `Level`=25, `MinLevel`=24, `RewardXPId`=5, `RewardMoneyMaxLevel`=12000, `Flags`=65544, `Title`='Panther Hunting', `Objectives`='Hunt 10 Young Panthers.', `Details`='If you want to be a part of the hunt with this crack group under Hemet Jr.''s leadership, you''re going to need to prove yourself an able panther hunter.  You should start out easy: just focus on the young panthers for now.  As you improve and gain experience as a hunter, you will undoubtedly find increasingly dangerous quarry.$b$bStart by heading east.  Return to me when you are a master panther hunter.', `CompletedText`='Return to Sir S. J. Erlgadin at Nesingwary''s Expedition in Northern Stranglethorn.', `WDBVerified`=15595 WHERE `Id`=190; -- Panther Mastery
UPDATE `quest_template` SET `Level`=26, `MinLevel`=24, `RewardXPId`=5, `RewardMoneyMaxLevel`=12600, `Flags`=589824, `Title`='Panther Stalking', `Objectives`='Hunt 10 Panthers.', `Details`='The youngest panthers fell easily before you.  Panthers that have come of age will naturally be stronger, and quicker, and more difficult to defeat.$b$bLarger panther tracks lead to the west.', `CompletedText`='Return to Sir S. J. Erlgadin at Nesingwary''s Expedition in Northern Stranglethorn.', `WDBVerified`=15595 WHERE `Id`=191; -- Panther Mastery
UPDATE `quest_template` SET `Level`=27, `MinLevel`=24, `RewardXPId`=5, `RewardMoneyMaxLevel`=13200, `Flags`=589824, `Title`='Panther Prowess', `Objectives`='Hunt 5 Shadowmaw Panthers.', `Details`='Now the hard part.  As panthers grow older, they become more wily, blending in with their environment and becoming difficult to spot.  These cunning panthers are known by the name \"shadowmaw\", for their tendency to suddenly appear out of the darkness... with a waiting mouth full of teeth.$b$bIf you want to prove yourself as a true panther hunter, shadowmaws are the only way to do so.  They prowl to the southeast, across the river.', `CompletedText`='Return to Sir S. J. Erlgadin at Nesingwary''s Expedition in Northern Stranglethorn.', `RequiredNpcOrGoCount1`=5, `WDBVerified`=15595 WHERE `Id`=192; -- Panther Mastery
UPDATE `quest_template` SET `Level`=28, `MinLevel`=24, `RewardXPId`=6, `RewardOrRequiredMoney`=7000, `RewardMoneyMaxLevel`=17100, `Flags`=134742016, `MinimapTargetMark`=16, `QuestGiverPortrait`=14572, `RewardItemId1`=0, `RewardItemCount1`=0, `RewardChoiceItemId1`=61109, `RewardChoiceItemId2`=61108, `RewardChoiceItemId3`=61107, `RewardChoiceItemCount1`=1, `RewardChoiceItemCount2`=1, `RewardChoiceItemCount3`=1, `Objectives`='Obtain the Fang of Bhag''thera.', `Details`='You''ve almost proven yourself to be a master hunter of panthers.  Yet there is one panther which has eluded your grasp.$b$bSongs are sung about a mighty panther by the name of Bhag''thera.  You will see if you can use your skills to kill the great beast.$b$bBringing the Fang of Bhag''thera to Erlgadin should be proof enough that you are a master panther hunter.', `CompletedText`='Return to Sir S. J. Erlgadin at Nesingwary''s Expedition in Northern Stranglethorn.', `QuestGiverTextWindow`='Stranglethorn''s largest panther.', `QuestGiverTargetName`='Bhag''thera', `WDBVerified`=15595 WHERE `Id`=193; -- Panther Mastery
UPDATE `quest_template` SET `Level`=25, `MinLevel`=24, `RewardXPId`=5, `RewardMoneyMaxLevel`=12000, `Flags`=65544, `Title`='Raptor Hunting', `Objectives`='Hunt 10 Stranglethorn Raptors.', `Details`='So you think your hunting skills are in tip-top shape?  I can put them to the test in a jiffy.  Head out into that jungle and kill ten Stranglethorn raptors.  We''ll see just how much of a big game hunter you are.$b$bAnd no, I won''t tell you where you can find them!  Locating the beasts is half the challenge.$b$bOkay, go west.', `CompletedText`='Return to Hemet Nesingwary Jr. at Nesingwary''s Expedition in Northern Stranglethorn.', `WDBVerified`=15595 WHERE `Id`=194; -- Raptor Mastery
UPDATE `quest_template` SET `Level`=26, `MinLevel`=24, `RewardXPId`=5, `RewardMoneyMaxLevel`=12600, `Flags`=589824, `Title`='Raptor Stalking', `Objectives`='Hunt 10 Lashtail Raptors.', `Details`='It is time to step up the challenge.  Venturing into the jungle and bagging 10 lashtail raptors should be sufficient.  They will certainly be stronger than the raptors you have already disposed of.$b$bThe lashtail raptors mainly stay southeast of here, near the Kal''ai Ruins.', `CompletedText`='Return to Hemet Nesingwary Jr. at Nesingwary''s Expedition in Northern Stranglethorn.', `WDBVerified`=15595 WHERE `Id`=195; -- Raptor Mastery
UPDATE `quest_template` SET `Level`=27, `MinLevel`=24, `RewardXPId`=5, `RewardMoneyMaxLevel`=13200, `Flags`=589824, `Title`='Raptor Prowess', `Objectives`='Hunt 10 Jungle Stalkers.', `Details`='A particularly cagey brand of raptor, known by locals as the \"Jungle Stalker\", prowls the forests to the south, across the river.  They are far more difficult to track down and kill than the other breeds you''ve been trying your luck at.$b$bKilling these Jungle Stalkers will undoubtedly make for a good tale around the fire.', `CompletedText`='Return to Hemet Nesingwary Jr. at Nesingwary''s Expedition in Northern Stranglethorn.', `WDBVerified`=15595 WHERE `Id`=196; -- Raptor Mastery
UPDATE `quest_template` SET `Level`=28, `MinLevel`=24, `RewardXPId`=6, `RewardOrRequiredMoney`=7000, `RewardMoneyMaxLevel`=17100, `Flags`=134742016, `MinimapTargetMark`=16, `QuestGiverPortrait`=8472, `RewardItemId1`=0, `RewardItemCount1`=0, `RewardChoiceItemId1`=61112, `RewardChoiceItemId2`=61111, `RewardChoiceItemId3`=61110, `RewardChoiceItemCount1`=1, `RewardChoiceItemCount2`=1, `RewardChoiceItemCount3`=1, `Objectives`='Hunt Tethis.', `Details`='Before returning to Nesingwary''s Expedition, you will have to complete the impossible: hunt the raptor that no other hunter has been able to capture.  That beast goes by the name of Tethis, and he''s been known to terrorize the southeastern corner of Northern Stranglethorn.$b$bBringing Tethis'' talon back to that dwarf hunter should be proof that you are no ordinary $r.', `CompletedText`='Return to Hemet Nesingwary Jr. at Nesingwary''s Expedition in Northern Stranglethorn.', `QuestGiverTextWindow`='Tethis survives solely on a diet of blueberries and Nesingwary hunters.', `QuestGiverTargetName`='Tethis', `WDBVerified`=15595 WHERE `Id`=197; -- Raptor Mastery
