UPDATE `quest_template` SET `MinLevel`=9, `Flags`=16392, `RewardChoiceItemId1`=58977, `RewardChoiceItemId2`=58976, `Objectives`='Bring 8 Tunnel Rat Ears to Mountaineer Stormpike in Algaz Station.', `Details`='We have a real infestation problem all over. Tunnel rat kobolds have moved into the foothills, setting up dens and fouling our land with their filth!$B$BWe want them eliminated. Hunt them, bring me their ears and earn their bounty.$B$BYou can find the greatest concentration of tunnel rat kobolds in and around the Silver Stream Mine to the east.', `CompletedText`='', `RequiredItemCount1`=8, `WDBVerified`=15595 WHERE `Id`=416; -- Rat Catching
UPDATE `quest_template` SET `Level`=10, `RewardXPId`=5, `RewardMoneyMaxLevel`=510, `Flags`=16384, `RewardReputationMask`=3, `RewardChoiceItemId1`=57560, `RewardChoiceItemId2`=57566, `RewardChoiceItemId3`=57562, `RewardChoiceItemId4`=57563, `RewardChoiceItemCount3`=1, `RewardChoiceItemCount4`=1, `Objectives`='Kill Mangeclaw.$B$BBring his Mangy Claw and Hildelve''s Journal to Pilot Hammerfoot at the South Gate Outpost.', `CompletedText`='', `WDBVerified`=15595 WHERE `Id`=417; -- A Pilot's Revenge
UPDATE `quest_template` SET `Level`=10, `MinLevel`=8, `RewardXPId`=7, `RewardOrRequiredMoney`=350, `RewardMoneyMaxLevel`=780, `Flags`=16392, `Objectives`='Bring 8 pieces of Bear Meat to Vidra Hearthstove in Thelsamar.', `Details`='There''s never a shortage of empty bellies here in Thelsamar, kids running in and out, workers from the excavation coming in after  a hard day''s work. We''re famous for our blood sausages, I don''t suppose you''ve ever tried them?$b$bNo? Well, around here you''ve got to work for your meals, and don''t think just because you''re a fancy $c, you''ll be any exception.$b$bAll I need is bear meat and rest is all in the preparation. You get me some of those, and leave the cooking to Vidra!', `CompletedText`='', `RequiredItemId1`=0, `RequiredItemId3`=0, `RequiredItemCount1`=0, `RequiredItemCount2`=8, `RequiredItemCount3`=0, `WDBVerified`=15595 WHERE `Id`=418; -- Thelsamar Blood Sausages
UPDATE `quest_template` SET `RewardXPId`=5, `RewardMoneyMaxLevel`=510, `Flags`=16392, `RewardReputationMask`=3, `RewardItemId1`=0, `RewardItemCount1`=0, `RewardChoiceItemId1`=58972, `RewardChoiceItemId2`=58971, `RewardChoiceItemId3`=58970, `RewardChoiceItemCount1`=1, `RewardChoiceItemCount2`=1, `RewardChoiceItemCount3`=1, `Objectives`='Pilot Hammerfoot at the South Gate Outpost wants you to find Pilot Hildelve.', `Details`='My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills. We were looking for a rare ore that''s needed for a high-grade blastpowder, and during our search he drove his engine up a steep hill and busted it!$B$BStill convinced that ore was in these mountains, Hildelve charged me to guard our engines while he continued on foot.$B$BIt''s been days, and I''ve heard some beastly growls north of Helm''s Bed Lake, west of the tunnel. Mori''s tough as nails, but I''m worried.$B$BPlease, $N. Find him.', `WDBVerified`=15595 WHERE `Id`=419; -- The Lost Pilot
