UPDATE `quest_template` SET `Level`=8, `RewardOrRequiredMoney`=225, `RewardMoneyMaxLevel`=420, `RewardReputationMask`=1, `RewardItemId1`=60240, `RewardItemCount1`=1, `RewardChoiceItemId1`=54868, `RewardChoiceItemId2`=9599, `Objectives`='Retrieve the Relics of Wakening.', `Details`='Gnarlpine invaders were seen ravaging the Ban''ethil Barrow Den, tucked in the hill to the west.$b$bThe slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help. The delicate hibernation ritual cannot be broken without the Relics of Wakening.$b$bJourney to the Den and retrieve the Raven Claw Talisman, Black Feather Quill, Sapphire of Sky, and Rune of Nesting. The druids store them in sacred chests.  Return them to me and I will prepare the awakening ritual.', `CompletedText`='Return to Athridas Bearmantle in Dolanaar.', `WDBVerified`=15595 WHERE `Id`=483; -- The Relics of Wakening
UPDATE `quest_template` SET `RewardMoneyMaxLevel`=10500, `Flags`=16392, `WDBVerified`=15595 WHERE `Id`=484; -- Young Crocolisk Skins
