UPDATE `quest_template` SET `Flags`=16392, `WDBVerified`=15595 WHERE `Id`=813; -- Finding the Antidote
UPDATE `quest_template` SET `Details`='Cook and clean--that''s all I do!$B$BYou want to eat, you get me some more meat! I don''t have all day to hunt and prepare food for all these louses. You got to learn to pull your own weight around here if you wanna be treated equal.$B$BGet me some Chunks of Boar Meat if you want to make yourself useful... or you don''t want to starve to death.', `WDBVerified`=15595 WHERE `Id`=814; -- <UNUSED>
