UPDATE `quest_template` SET `Flags`=16392, `WDBVerified`=15595 WHERE `Id`=6383; -- The Ashenvale Hunt
UPDATE `quest_template` SET `Level`=7, `MinLevel`=5, `ZoneOrSort`=14, `RewardOrRequiredMoney`=85, `RewardMoneyMaxLevel`=180, `Flags`=262144, `RewardReputationMask`=3, `Objectives`='Buy a wind rider to Orgrimmar from the wind rider master Burok, then bring Grimtak''s Meats to Gryshka in Orgrimmar.', `Details`='For just a few coins I will have a wind rider bring you to Orgrimmar.  When you get there, you can take Grimtak''s meats to Gryshka.  Her inn is in the Valley of Strength.$B$BSpeak with me again when you are ready for the journey.', `CompletedText`='Buy a wind rider to Orgrimmar from the wind rider master Devrak, then bring Zargh''s Meats to Gryshka in Orgrimmar.', `WDBVerified`=15595 WHERE `Id`=6384; -- Ride to Orgrimmar
UPDATE `quest_template` SET `Level`=7, `MinLevel`=5, `ZoneOrSort`=14, `RewardMoneyMaxLevel`=90, `RewardReputationMask`=3, `Details`='I''ve written a letter of thanks to Grimtak.  Will you deliver it for me?  If you''ve already been to the Razor Hill and spoken with their wind rider master, then you can fly a wind rider back there.$B$BTake my letter to Doras, the wind rider master of Orgrimmar, and speak with him about transport to Razor Hill.', `CompletedText`='Bring Gryshka''s Letter to Doras in Orgrimmar.', `WDBVerified`=15595 WHERE `Id`=6385; -- Doras the Wind Rider Master
UPDATE `quest_template` SET `Level`=7, `MinLevel`=5, `ZoneOrSort`=14, `RewardXPId`=5, `RewardOrRequiredMoney`=175, `RewardMoneyMaxLevel`=390, `Flags`=262144, `RewardReputationMask`=3, `Title`='Return to Razor Hill', `Objectives`='Buy a wind rider to Razor Hill from the wind rider master Doras, then bring Gryshka''s Letter to Grimtak at Razor Hill.', `Details`='My wind riders are trained to fly to many different places, as long as you have already been to that place and spoken with the wind rider master there.$B$BYou have been to Razor Hill and spoken to their wind rider master Burok, so now you can fly directly to him from here.  Once you''re at Razor Hill, you can deliver Gryshka''s letter to Grimtak.$B$BSpeak with me when you are ready to go.', `CompletedText`='Buy a wind rider to the Crossroads from the wind rider master Doras, then bring Gryshka''s Letter to Zargh at the Crossroads.', `WDBVerified`=15595 WHERE `Id`=6386; -- Return to the Crossroads.
UPDATE `quest_template` SET `Level`=7, `MinLevel`=5, `ZoneOrSort`=1, `RewardXPId`=4, `RewardMoneyMaxLevel`=270, `RewardReputationMask`=3, `Objectives`='Bring Gremlock''s List to Brolan Galebeard in Kharanos.', `Details`='I see a lot of young dwarves at my door, eager to learn the trade of cooking.  And if there''s one thing a cook needs more than anything, it''s a cleaver!$B$BI have a list of students who scored high in their lessons and earned an honorary cleaver.  Take my list to Golnir Bouldertoe in Ironforge.  He''ll get the cleavers ready.$B$BThe fastest way to Ironforge is on a gryphon, so bring the list to our gryphon master, Brolan Galebeard, and speak with him about transport to Ironforge.', `WDBVerified`=15595 WHERE `Id`=6387; -- Honor Students
UPDATE `quest_template` SET `Level`=7, `MinLevel`=5, `ZoneOrSort`=1, `RewardXPId`=4, `RewardMoneyMaxLevel`=270, `RewardReputationMask`=3, `Objectives`='Bring the Honorary Cleavers to Gryth Thurden in Ironforge.', `Details`='Here are the honorary cleavers for Gremlock''s students.  If you''ve already been to Kharanos, then you should fly a gryphon back there!$B$BTake the cleavers to our gryphon master, Gryth Thurden, and speak with him about a ride back to Kharanos.', `WDBVerified`=15595 WHERE `Id`=6388; -- Gryth Thurden
