UPDATE `quest_template` SET `Level`=3, `MinLevel`=3, `RewardXPId`=5, `RewardMoneyMaxLevel`=150, `Flags`=524416, `RewardFactionValueId1`=5, `Title`='Arcane Missiles', `Objectives`='Learn Arcane Missiles from Julia Sunstriker. Locate a Training Dummy outside the Sunspire and practice using Arcane Missiles 2 times.', `Details`='It is time for your first lesson in the arcane arts. I want to show you a new spell, Arcane Missiles.$B$BYou won''t be able to use this spell all the time, but each time you cast an offensive spell, there is a chance you will be able to cast Arcane Missiles.$B$BGo outside, find a training dummy, and try it for yourself.', `CompletedText`='Return to Julia Sunstriker at the Sunspire on Sunstrider Isle.
', `RequiredNpcOrGo1`=44175, `RequiredNpcOrGoCount1`=2, `RequiredSpell`=5143, `ObjectiveText1`='Practice Arcane Missiles', `WDBVerified`=15595 WHERE `Id`=10068; -- Well Watcher Solanian
UPDATE `quest_template` SET `Level`=3, `MinLevel`=3, `RewardXPId`=5, `RewardMoneyMaxLevel`=150, `Flags`=524416, `RewardFactionValueId1`=5, `Title`='Ways of the Light', `Objectives`='Learn Judgement and Seal of Righteousness from Jesthenis Sunstriker. Cast Seal of Righteousness on yourself, then locate a Training Dummy outside the Sunspire and use Judgement.', `Details`='It is time for your first lesson in the ways of the Light, $N. I want to show you two techniques that you can use to help yourself and your allies in combat.$B$BFirst is Seal of Righteousness. Under its effects, all of your melee strikes will deal extra holy damage.$B$BWhile your seal is active, you may periodically use Judgement to inflict additional damage to your opponent. Go, find a training dummy and practice your new techniques.', `CompletedText`='Return to Jesthenis Sunstriker Sunspire on Sunstrider Isle.
', `RequiredNpcOrGo1`=44175, `RequiredNpcOrGo2`=44420, `RequiredNpcOrGoCount1`=1, `RequiredNpcOrGoCount2`=1, `RequiredSpell`=20154, `ObjectiveText1`='Practice Judgement', `ObjectiveText2`='Learn Judgement', `WDBVerified`=15595 WHERE `Id`=10069; -- Well Watcher Solanian
UPDATE `quest_template` SET `Level`=3, `MinLevel`=3, `RewardXPId`=5, `RewardMoneyMaxLevel`=150, `Flags`=524416, `RewardFactionValueId1`=5, `Title`='Steady Shot', `Objectives`='Learn Steady Shot from Ranger Sallina. Locate a Training Dummy outside the Sunspire and practice using Steady Shot 5 times.', `Details`='And now, it is time for your first lesson.$B$BI will show you a shot that I use often. I''m sure you''ll find it useful, too.$B$BOnce our lesson has ended, find a training dummy and practice your new skill.', `CompletedText`='Return to Ranger Sallina in the Sunspire on Sunstrider Isle.', `RequiredNpcOrGo1`=44175, `RequiredNpcOrGoCount1`=5, `RequiredSpell`=56641, `ObjectiveText1`='Practice Steady Shot', `WDBVerified`=15595 WHERE `Id`=10070; -- Well Watcher Solanian
UPDATE `quest_template` SET `Level`=3, `MinLevel`=3, `RewardXPId`=5, `RewardMoneyMaxLevel`=150, `Flags`=524416, `RewardFactionValueId1`=5, `Title`='Evisceration', `Objectives`='Learn Eviscerate from Pathstalker Kariel. Locate a Training Dummy outside the Sunspire and practice using Eviscerate 3 times.', `Details`='I want to teach you a new technique. This is a great way to complete a combination of combat maneuvers for a strong finish. Try it after hitting your opponent with at least one Sinister Strike. The more Sinister Strikes you land, the stronger your finishing attack will be.$B$BFind one of the training dummies outside and give it a try. ', `CompletedText`='Return to Pathstalker Kariel at the Sunspire on Sunstrider Isle.', `RequiredNpcOrGo1`=44175, `RequiredNpcOrGoCount1`=3, `RequiredSpell`=2098, `ObjectiveText1`='Practice Eviscerate', `WDBVerified`=15595 WHERE `Id`=10071; -- Well Watcher Solanian
UPDATE `quest_template` SET `Level`=3, `MinLevel`=3, `RewardXPId`=5, `RewardMoneyMaxLevel`=150, `Flags`=524416, `RewardFactionValueId1`=5, `Title`='Healing the Wounded', `Objectives`='Learn Flash Heal from Matron Arena. Practice casting Flash Heal 5 times on Wounded Outrunners.', `Details`='The time has come for your first lesson in the healing arts. I want to teach you a very basic healing spell that you can use to quickly heal the injuries of an ally.$B$BOnce we''ve finished our lesson, I want you to practice your new healing skills on some of the wounded outrunners who have taken refuge in the Sunspire.', `CompletedText`='Return to Matron Arena Sunspire on Sunstrider Isle.', `RequiredNpcOrGo1`=44175, `RequiredNpcOrGoCount1`=5, `RequiredSpell`=2061, `ObjectiveText1`='Heal Wounded Outrunners', `WDBVerified`=15595 WHERE `Id`=10072; -- Well Watcher Solanian
UPDATE `quest_template` SET `Level`=3, `MinLevel`=3, `RewardXPId`=5, `RewardMoneyMaxLevel`=150, `Flags`=524416, `RewardFactionValueId1`=5, `Title`='Immolation', `Objectives`='Learn Immolate from Summoner Teli''Larien. Locate a Training Dummy outside the Sunspire and practice casting Immolate 5 times.', `Details`='By now, you''ve heard the rumors about our kind, the warlocks. Pay them no mind; they are uttered by those jealous of our fearsome powers.$B$BAllow me to show you a new spell, one that will allow you to set your enemy aflame and make him burn for a time. Once our lesson is finished, I want you to practice using this new spell on the training dummies outside the Sunspire.', `CompletedText`='Return to Summoner Teli''Larien at the Sunspire on Sunstrider Isle.', `RequiredNpcOrGo1`=44175, `RequiredNpcOrGoCount1`=5, `RequiredSpell`=348, `ObjectiveText1`='Practice Immolate', `WDBVerified`=15595 WHERE `Id`=10073; -- Well Watcher Solanian
